let mineralReference=null;
const groupLabel=document.createElement('label');groupLabel.textContent='Recorte mineral';const groupSelect=document.createElement('select');groupSelect.id='explore-mineral-group';groupSelect.innerHTML='<option value="">Todas as substâncias</option><option value="estrategico">Estratégicos · 2021</option><option value="alta_tecnologia">Alta tecnologia · 2021</option>';groupLabel.append(groupSelect);$('filters').append(groupLabel);
const matchesBeforeGroup=matchesExtra;matchesExtra=function(r){if(!matchesBeforeGroup(r))return false;if(!groupSelect.value)return true;if(!mineralReference)return false;const norm=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toUpperCase().trim().replace(/^MINERIO DE /,'');const list=groupSelect.value==='alta_tecnologia'?mineralReference.groups.alta_tecnologia:Object.values(mineralReference.groups).flat(),allowed=new Set(list.map(norm));return r.sub.split(';').some(t=>allowed.has(mineralReference.aliases[norm(t)]||norm(t)))};
groupSelect.onchange=()=>{page=0;render()};const clearBeforeGroup=$('clear').onclick;$('clear').onclick=()=>{groupSelect.value='';clearBeforeGroup()};
const previousExploreRender=render;
render=function(){previousExploreRender();if(!data)return;const rs=[1,2,3,4,5,6,7,8],vals=rs.map(n=>[6,7].includes(n)?0:filtered.filter(r=>r.r===n).reduce((s,r)=>s+(r.v||0),0));let total=0;const totals=vals.map(v=>total+=v),max=Math.max(total,1),x=i=>50+i*66,y=v=>215-180*v/max;let svg='<svg viewBox="0 0 610 260" role="group" aria-label="Clique em uma das oito rodadas para filtrar">';rs.forEach((n,i)=>{const context=n===6?'Avaliação social':n===7?'Edital cancelado':money(vals[i]);svg+=`<g tabindex="0" role="button" data-filter-round="${n}" aria-label="Filtrar ${n}ª rodada: ${esc(context)}"><title>${n}ª rodada: ${esc(context)}; acumulado ${money(totals[i])}</title><rect x="${x(i)}" y="${y(vals[i])}" width="34" height="${Math.max(2,215-y(vals[i]))}" fill="${[6,7].includes(n)?'#69788a':'#1351b4'}" rx="3"/><text x="${x(i)+17}" y="242" text-anchor="middle">${n}ª${[6,7].includes(n)?'*':''}</text><rect x="${x(i)-5}" y="20" width="48" height="238" fill="transparent"/></g>`});svg+=`<polyline points="${totals.map((v,i)=>(x(i)+17)+','+y(v)).join(' ')}" fill="none" pointer-events="none" stroke="#168821" stroke-width="3"/></svg>`;$('roundbars').innerHTML='<div class="time-legend"><span><i></i>Lances da rodada</span><span><i class="line-key"></i>Acumulado na seleção</span></div><div class="chart">'+svg+'</div><p class="caption">Clique na rodada para filtrar gráficos, mapa e tabela. * 6ª: avaliação social; 7ª: cancelada. Contribuição financeira zero, sem equivaler a arrematação por zero reais.</p>';
const statuses=[...new Set(filtered.map(r=>r.s))];$('outcomes').innerHTML=statuses.map(s=>`<button class="filter-bar" data-filter-result="${esc(s)}">${bar(s,filtered.filter(r=>r.s===s).length,filtered.length,colors[s]||'#69788a')}</button>`).join('')||'<p>Sem áreas no recorte.</p>';
};
$('roundbars').onclick=e=>{const b=e.target.closest('[data-filter-round]');if(!b)return;$('round').value=$('round').value===b.dataset.filterRound?'':b.dataset.filterRound;page=0;render()};$('roundbars').onkeydown=e=>{if(['Enter',' '].includes(e.key)&&e.target.dataset.filterRound){e.preventDefault();e.target.dispatchEvent(new MouseEvent('click',{bubbles:true}))}};$('outcomes').onclick=e=>{const b=e.target.closest('[data-filter-result]');if(!b)return;window.onlyOthers=false;const v=b.dataset.filterResult;if(![...$('result').options].some(o=>o.value===v))$('result').add(new Option(v,v));$('result').value=$('result').value===v?'':v;page=0;render()};
$('dots').onclick=e=>{const el=e.target.closest('[data-index]');if(!el)return;const r=filtered[+el.dataset.index];if(!r)return;$('process-filter').value=formatProcess(r.p);page=0;render()};
const loadNotice=document.createElement('div');loadNotice.className='selection-note';loadNotice.setAttribute('role','status');loadNotice.id='explorer-load-notice';loadNotice.innerHTML='<span>Preparando a exploração das áreas…</span> <button type="button" class="button" hidden>Tentar novamente</button>';$('explore').prepend(loadNotice);
window.explorerLoading=message=>{loadNotice.hidden=false;loadNotice.querySelector('span').textContent=message;loadNotice.querySelector('button').hidden=true};
window.explorerLoaded=()=>{loadNotice.hidden=true};
window.explorerFailed=message=>{loadNotice.hidden=false;loadNotice.querySelector('span').textContent='O carregamento não terminou. '+message;loadNotice.querySelector('button').hidden=false};
async function startExplorer(retry=false){try{if(retry){window.metadataReady=loadData();window.overviewReady=loadOverview()}await ensureAreas();try{mineralReference=await fastJSON('pesquisa/mineral-reference.json')}catch(e){if(new URLSearchParams(location.search).has('group'))throw Error('Não foi possível carregar a classificação mineral. Tente novamente.')}const q=new URLSearchParams(location.search);for(const [key,id]of [['round','round'],['uf','state'],['result','result'],['process','process-filter']])if(q.has(key)){const control=$(id),v=q.get(key);if(control.tagName==='SELECT'&&![...control.options].some(o=>o.value===v))control.add(new Option(v,v));control.value=v}if(q.has('group'))groupSelect.value=q.get('group');window.onlyOthers=false;render();explorerLoaded()}catch(e){explorerFailed(e.message)}}
loadNotice.querySelector('button').onclick=()=>startExplorer(true);
document.querySelector('[data-view="explore"]').click();
startExplorer();
